import{_ as p,a0 as l,w as o,s as r,ao as h,I as t,x as e,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 下如何查看一个进程的运行时间 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 下如何查看一个进程的运行时间 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 下如何查看一个进程的运行时间 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 下如何查看一个进程的运行时间 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160801 Linux how long a process has been running","title":"在 Linux 下如何查看一个进程的运行时间","tag":"201608","desc":""},"relativePath":"201608/20160801 Linux how long a process has been running.md","filePath":"[post].md"}'),d={name:"201608/20160801 Linux how long a process has been running.md"};function g(u,s,b,k,c,f){const i=l("Link");return o(),r("div",null,[s[13]||(s[13]=h(`<h1 id="在-linux-下如何查看一个进程的运行时间" tabindex="-1">在 Linux 下如何查看一个进程的运行时间 <a class="header-anchor" href="#在-linux-下如何查看一个进程的运行时间" aria-label="Permalink to “在 Linux 下如何查看一个进程的运行时间”">​</a></h1><p><img src="http://s0.cyberciti.org/images/category/old/linux-logo.png" alt=""></p><blockquote><p>我是一个 Linux 系统的新手。我该如何在我的 Ubuntu 服务器上查看一个进程（或者根据进程 id 查看）已经运行了多久？</p></blockquote><p>你需要使用 ps 命令来查看关于一组正在运行的进程的信息。ps 命令提供了如下的两种格式化选项。</p><ol><li>etime 显示了自从该进程启动以来，经历过的时间，格式为 <code>[[DD-]hh:]mm:ss</code>。</li><li>etimes 显示了自该进程启动以来，经历过的时间，以秒的形式。</li></ol><h3 id="如何查看一个进程已经运行的时间" tabindex="-1">如何查看一个进程已经运行的时间？ <a class="header-anchor" href="#如何查看一个进程已经运行的时间" aria-label="Permalink to “如何查看一个进程已经运行的时间？”">​</a></h3><p>你需要在 ps 命令之后添加 -o etimes 或者 -o etime 参数。它的语法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ps -p {PID-HERE} -o etime</span></span>
<span class="line"><span>ps -p {PID-HERE} -o etimes</span></span></code></pre></div><h4 id="第一步-找到一个进程的-pid-openvpn-为例" tabindex="-1">第一步：找到一个进程的 PID (openvpn 为例) <a class="header-anchor" href="#第一步-找到一个进程的-pid-openvpn-为例" aria-label="Permalink to “第一步：找到一个进程的 PID (openvpn 为例)”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pidof openvpn</span></span>
<span class="line"><span>6176</span></span></code></pre></div><h4 id="第二步-openvpn-进程运行了多长时间" tabindex="-1">第二步：openvpn 进程运行了多长时间？ <a class="header-anchor" href="#第二步-openvpn-进程运行了多长时间" aria-label="Permalink to “第二步：openvpn 进程运行了多长时间？”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o etime</span></span></code></pre></div><p>或者</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o etimes</span></span></code></pre></div><p>隐藏输出头部：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o etime=</span></span>
<span class="line"><span>$ ps -p 6176 -o etimes=</span></span></code></pre></div><p>样例输出：</p><p><img src="http://s0.cyberciti.org/uploads/faq/2016/08/How-to-check-how-long-a-process-has-been-running.jpg" alt=""></p><p>这个 6176 就是你想查看的进程的 PID。在这个例子中，我查看的是 openvpn 进程。你可以按照你的需求随意的更换 openvpn 进程名或者是 PID。在下面的例子中，我打印了 PID、执行命令、运行时间、用户 ID、和用户组 ID：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -p 6176 -o pid,cmd,etime,uid,gid</span></span></code></pre></div><p>样例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>  PID CMD                             ELAPSED   UID   GID</span></span>
<span class="line"><span> 6176 /usr/sbin/openvpn --daemon        15:25 65534 65534</span></span></code></pre></div><hr>`,23)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/"},{default:n(()=>[...s[0]||(s[0]=[e("http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=e("作者：",-1)),a(i,{href:"http://www.cyberciti.biz/faq/how-to-check-how-long-a-process-has-been-running/"},{default:n(()=>[...s[2]||(s[2]=[e("VIVEK GITE",-1)])]),_:1}),s[6]||(s[6]=e(" 译者：",-1)),a(i,{href:"https://github.com/MikeCoder"},{default:n(()=>[...s[3]||(s[3]=[e("MikeCoder",-1)])]),_:1}),s[7]||(s[7]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[e("LCTT",-1)])]),_:1}),s[11]||(s[11]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[e("Linux中国",-1)])]),_:1}),s[12]||(s[12]=e(" 荣誉推出",-1))])])}const v=p(d,[["render",g]]);export{C as __pageData,v as default};
